import pg from 'pg';
import {PostgresAgentMemory} from '../../dist/index.js';
const pool=new pg.Pool({connectionString:process.env.APP_MIXER_TEST_POSTGRES_URL,options:`-c search_path=${process.env.APP_MIXER_TEST_SCHEMA}`}),phase=process.env.APP_MIXER_TEST_PHASE;
const hold=()=>new Promise(()=>{});
const operation=process.env.APP_MIXER_TEST_OPERATION??'write';
const store=new PostgresAgentMemory({enabled:true,audit:true,maxEntries:10,maxTtlMs:10000,clock:()=>100,authorize:()=>true,query:(sql,args)=>pool.query(sql,args),transaction:async operation=>{const client=await pool.connect();try{await client.query('BEGIN');const result=await operation(async(sql,args)=>{const result=await client.query(sql,args);if(phase==='after-mutation'&&sql.startsWith('UPDATE app_mixer_agent_memories')){process.send(phase);await hold();}return result;});if(phase==='before-commit'){process.send('before-commit');await hold();}await client.query('COMMIT');if(phase==='after-commit'){process.send('after-commit');await hold();}return result;}catch(error){await client.query('ROLLBACK');throw error;}finally{client.release();}}});
try{const actor={tenantId:'tenant',principalId:'worker'},scope={tenantId:'tenant',agentId:'agent',owner:{kind:'organization',id:'org'},kind:'semantic'};if(operation==='erase')await store.eraseScope(actor,scope);else await store.put(actor,scope,phase,{phase},{expectedRevision:null,expiresAt:500,provenance:{kind:'run',id:'run'}});throw Error('Expected termination');}catch(error){process.send({error:String(error)});process.exitCode=1;await pool.end();}
